using System;using System.Collections.Generic;using System.Linq;using System.IO;using System.Security.Cryptography;using System.Runtime.CompilerServices;using System.Text;
using TownOfHost;using TownOfHost.Roles.Core;using TownOfHost.Roles.Core.Interfaces;
static class Program {
static int passed,failed;
static void Check(bool ok,string why="assertion"){if(!ok)throw new Exception(why);}
static void Reset(){Camouflage.Init();PlayerCatch.AllPlayerControls.Clear();CustomRoleManager.AllActiveRoles.Clear();TownOfHost.Main.CheckShapeshift.Clear();TownOfHost.Main.ShapeshiftTarget.Clear();TownOfHost.Main.AfterMeetingDeathPlayers.Clear();TownOfHost.Main.DontGameSet=false;GameStates.IsLobby=GameStates.IsOutro=GameStates.task=false;GameStates.turntimer=5;Options.CurrentGameMode=CustomGameMode.Standard;Options.CommsCamouflage.Value=Options.NoGameEnd.Value=Options.OptionSabotageFinAllKill.Value=Options.OutroCrewWinreasonchenge.Value=false;AmongUsClient.Instance=new();GameManager.Instance=new();ShipStatus.Instance=new();CustomWinnerHolder.ResetAndSetWinner(CustomWinner.Default);CustomWinnerHolder.CantWinPlayerIds.Clear();CustomWinnerHolder.NeutralWinnerIds.Clear();CustomRpcSender.All.Clear();CustomRpcSender.ThrowSend=CustomRpcSender.ThrowWrite=CustomRpcSender.ThrowAfterSend=false;Logger.Warnings.Clear();GameDataSerializePatch.SerializeMessageCount=0;Probe.EndCalls=Probe.Coroutines=Probe.WinnerRpc=Probe.Summaries=Probe.Syncs=0;Probe.ModClient=true;GameEndChecker.SetPredicate(new NormalGameEndPredicate());}
static PlayerControl P(byte id,CustomRoleTypes team=CustomRoleTypes.Crewmate,int saved=2){var p=new PlayerControl{PlayerId=id,Team=team,Role=team==CustomRoleTypes.Impostor?CustomRoles.Impostor:CustomRoles.Crewmate,Data=new(){PlayerId=id,NetId=(uint)(100+id)},NetId=(uint)(10+id)};PlayerCatch.AllPlayerControls.Add(p);PlayerState.GetByPlayerId(id).IsDead=false;Camouflage.PlayerSkins[id]=new(){RawColor=saved};Camouflage.RememberColor(id,saved);if(id==0)PlayerControl.LocalPlayer=p;return p;}
static void Population(int imp,int crew){for(byte i=0;i<imp+crew;i++)P(i,i<imp?CustomRoleTypes.Impostor:CustomRoleTypes.Crewmate);}
static void Test(string name,Action run){try{Reset();run();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+" "+e.Message);}}
static string Read(string relative,[CallerFilePath]string file="")=>File.ReadAllText(Path.GetFullPath(Path.Combine(Path.GetDirectoryName(file),"../..",relative))).Replace("\r\n","\n");
static string Sha(string s)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s)));
static void Main(){
Test("generated production Prefix and coroutine exactly match source",()=>{var s=Read("Patches/CheckGameEndPatch.cs");var prefix=s[s.IndexOf("        public static bool Prefix()")..s.IndexOf("        public static void StartEndGame")].Trim();Check(Sha(prefix)==GeneratedHashes.prefix);var co=s[s.IndexOf("        public static void StartEndGame")..s.IndexOf("        private static void SetRoleSummaryText")].Trim();Check(Sha(co)==GeneratedHashes.coroutine);});
Test("ordinary impostor population condition exactly matches source",()=>{var s=Read("Patches/GameEndPredicate/NormalGameEndPredicate.cs");s=s[(s.IndexOf("*/")+2)..];int end=s.IndexOf("//インポスター勝利"),start=s.LastIndexOf("else if (",end,StringComparison.Ordinal);var condition=s[start..end].Trim()[5..];Check(Sha(condition)==GeneratedHashes.population_condition);});
Test("meeting callback delegates to guarded batch with original delay",()=>{var s=Read("Patches/PlayerContorols/ReportDeadBodyPatch.cs");int x=s.IndexOf("Camouflage.RestoreAllForMeeting();");Check(x>=0&&s[x..(x+120)].Contains("0.35f, \"SetSkin\""));});
Test("start and intro capture primitive before native outfit copies",()=>{foreach(var path in new[]{"Patches/IntroPatch.cs","Patches/onGameStartedPatch.cs"}){var s=Read(path);Check(s.Contains("Camouflage.RememberColor(pc.PlayerId, colorId);"));}});
Test("full outfit equality preserved for valid values",()=>{var a=new NetworkedPlayerInfo.PlayerOutfit();var b=new NetworkedPlayerInfo.PlayerOutfit();Check(a.Compare(b));b.RawPet="other";Check(!a.Compare(b));});
Test("full comparison failure returns unequal and warns once",()=>{var a=new NetworkedPlayerInfo.PlayerOutfit{BadPet=true};var b=new NetworkedPlayerInfo.PlayerOutfit();for(int i=0;i<100;i++)Check(!a.Compare(b));Check(Logger.Warnings.Count==1);});
foreach(bool? force in new bool?[]{false,true,null})Test("restore never reads native PetId force="+force,()=>{var p=P(0);p.Data.DefaultOutfit.BadPet=true;Camouflage.PlayerSkins[0].BadPet=true;Camouflage.RpcSetSkin(p,ForceRevert:true,RevertToDefault:true,force:force);Check(p.Data.DefaultOutfit.RawColor==2);Check(p.Data.DefaultOutfit.PetReads==0&&Camouflage.PlayerSkins[0].PetReads==0);Check(CustomRpcSender.All.All(x=>x.Disposed&&x.Sent));});
Test("managed color survives broken legacy color and pet",()=>{var p=P(0,saved:7);Camouflage.PlayerSkins[0].BadColor=Camouflage.PlayerSkins[0].BadPet=true;Camouflage.RpcSetSkin(p);Check(p.Data.DefaultOutfit.RawColor==7&&Camouflage.PlayerSkins[0].PetReads==0);});
Test("normal matching color sends no redundant packet",()=>{var p=P(0,saved:1);p.Data.DefaultOutfit.BadPet=true;Camouflage.RpcSetSkin(p);Check(CustomRpcSender.All.Count==0&&p.Data.DefaultOutfit.PetReads==0);});
Test("forced meeting sends the existing SetColor frame",()=>{var p=P(0,saved:1);Camouflage.RestoreAllForMeeting();var s=CustomRpcSender.All.Single();Check(s.Payload.SequenceEqual(new long[]{10,(byte)RpcCalls.SetColor,100,1})&&s.Sent&&s.Disposed);});
Test("unregistered legacy cache can provide primitive fallback",()=>{var p=P(0);Camouflage.Init();Camouflage.PlayerSkins[0]=new(){RawColor=9,BadPet=true};Camouflage.RpcSetSkin(p);Check(p.Data.DefaultOutfit.RawColor==9&&Camouflage.PlayerSkins[0].PetReads==0);});
Test("bad legacy primitive falls back to current safe color",()=>{var p=P(0);Camouflage.Init();Camouflage.PlayerSkins[0]=new(){BadColor=true};Camouflage.RpcSetSkin(p);Check(p.Data.DefaultOutfit.RawColor==1&&CustomRpcSender.All.Count==0&&Logger.Warnings.Count>0);});
Test("bad live color can use saved managed color",()=>{var p=P(0);p.Data.DefaultOutfit.BadColor=true;Camouflage.RpcSetSkin(p);Check(p.Data.DefaultOutfit.RawColor==2&&CustomRpcSender.All.Single().Sent);});
Test("no readable color skips cosmetic safely",()=>{var p=P(0);Camouflage.Init();p.Data.DefaultOutfit.BadColor=true;Camouflage.PlayerSkins[0]=new(){BadColor=true};Camouflage.RestoreAllForGameEnd();Check(CustomRpcSender.All.Count==0&&Logger.Warnings.Count>0);});
Test("out of palette value never sent",()=>{var p=P(0,saved:1000);Camouflage.RpcSetSkin(p);Check(p.Data.DefaultOutfit.RawColor==1&&CustomRpcSender.All.Count==0);});
Test("shapeshift uses source saved color",()=>{var p=P(0);P(1,saved:8);TownOfHost.Main.CheckShapeshift[0]=true;TownOfHost.Main.ShapeshiftTarget[0]=1;Camouflage.RpcSetSkin(p);Check(p.Data.DefaultOutfit.RawColor==8);});
Test("default revert ignores shapeshift source",()=>{var p=P(0);P(1,saved:8);TownOfHost.Main.CheckShapeshift[0]=true;TownOfHost.Main.ShapeshiftTarget[0]=1;Camouflage.RpcSetSkin(p,RevertToDefault:true);Check(p.Data.DefaultOutfit.RawColor==2);});
Test("missing shapeshift target falls back without indexing exception",()=>{var p=P(0);TownOfHost.Main.CheckShapeshift[0]=true;Camouflage.RpcSetSkin(p);Check(p.Data.DefaultOutfit.RawColor==2&&Logger.Warnings.Count==1);});
Test("active camouflage still uses gray fifteen",()=>{var p=P(0);Camouflage.IsCamouflage=true;Camouflage.RpcSetSkin(p);Check(p.Data.DefaultOutfit.RawColor==15);});
Test("force revert from active camouflage restores original",()=>{var p=P(0);Camouflage.IsCamouflage=true;Camouflage.RpcSetSkin(p,ForceRevert:true);Check(p.Data.DefaultOutfit.RawColor==2);});
Test("vent queue deduplicates then restores after exit",()=>{var p=P(0);p.inVent=true;for(int i=0;i<100;i++)Camouflage.RpcSetSkin(p);Check(Camouflage.ventplayr.SequenceEqual(new byte[]{0}));p.inVent=false;Camouflage.RpcSetSkin(p);Check(Camouflage.ventplayr.Count==0&&p.Data.DefaultOutfit.RawColor==2);});
foreach(string bad in new[]{"dummy","disconnected","no-data","null"})Test("skip unavailable cosmetic target "+bad,()=>{var p=P(bad=="dummy"?(byte)254:(byte)0);if(bad=="disconnected")p.Data.Disconnected=true;if(bad=="no-data")p.Data=null;Camouflage.RpcSetSkin(bad=="null"?null:p);Check(CustomRpcSender.All.Count==0);});
foreach(string fault in new[]{"set","partial-set","write","send"})Test("packet failure disposes; rollback only before submission "+fault,()=>{var p=P(0);if(fault=="set")p.ThrowColor=true;if(fault=="partial-set")p.ThrowAfterSetOnce=true;if(fault=="write")CustomRpcSender.ThrowWrite=true;if(fault=="send")CustomRpcSender.ThrowSend=true;Camouflage.RestoreAllForGameEnd();Check(CustomRpcSender.All.All(s=>s.Disposed)&&!CustomRpcSender.All.Any(s=>s.Sent));if(fault!="set")Check(p.Data.DefaultOutfit.RawColor==(fault=="send"?2:1));});
Test("post-send failure preserves submitted color and never resends",()=>{var p=P(0);CustomRpcSender.ThrowAfterSend=true;for(int i=0;i<100;i++)Camouflage.RestoreAllForGameEnd();var sender=CustomRpcSender.All.Single();Check(sender.Sent&&sender.Disposed&&p.Data.DefaultOutfit.RawColor==2&&Logger.Warnings.Count==1&&Logger.Warnings[0].Contains("send_outcome_unknown"));});
Test("end cosmetic failure is not retried or logged every frame",()=>{P(0);CustomRpcSender.ThrowSend=true;for(int i=0;i<500;i++)Camouflage.RestoreAllForGameEnd();Check(CustomRpcSender.All.Count==1&&Logger.Warnings.Count==1);});
Test("new round clears end attempts and stale color and vents",()=>{var p=P(0);Camouflage.RestoreAllForGameEnd();Camouflage.ventplayr.Add(0);Camouflage.Init();Check(Camouflage.ventplayr.Count==0);Camouflage.RememberColor(0,6);Camouflage.RestoreAllForGameEnd();Check(p.Data.DefaultOutfit.RawColor==6);});
Test("meeting shapeshift failure does not block next player",()=>{var a=P(0);var b=P(1);a.shapeshifting=a.ThrowShift=true;Camouflage.RestoreAllForMeeting();Check(b.Data.DefaultOutfit.RawColor==2&&Logger.Warnings.Count==1);});
Test("meeting clears shapeshift and restores every valid player",()=>{var a=P(0);var b=P(1);a.shapeshifting=true;a.Data.DefaultOutfit.BadPet=b.Data.DefaultOutfit.BadPet=true;Camouflage.RestoreAllForMeeting();Check(!a.shapeshifting&&a.ShiftCalls==1&&a.Data.DefaultOutfit.RawColor==2&&b.Data.DefaultOutfit.RawColor==2);});
foreach(var population in new[]{(3,3),(3,0),(1,1),(1,0)})Test("actual end flow impostor parity "+population,()=>{Population(population.Item1,population.Item2);foreach(var p in PlayerCatch.AllPlayerControls){p.Data.DefaultOutfit.BadPet=true;Camouflage.PlayerSkins[p.PlayerId].BadPet=true;}GameEndChecker.Prefix();Check(Probe.EndCalls==1&&CustomWinnerHolder.WinnerTeam==CustomWinner.Impostor&&CustomWinnerHolder.WinnerIds.Count==population.Item1&&!ShipStatus.Instance.enabled);Check(PlayerCatch.AllPlayerControls.All(p=>p.Data.DefaultOutfit.PetReads==0));Check(GameDataSerializePatch.SerializeMessageCount==0);});
Test("ordinary nonwinning population stays in game",()=>{Population(2,3);GameEndChecker.Prefix();Check(Probe.EndCalls==0&&CustomWinnerHolder.WinnerTeam==CustomWinner.Default&&ShipStatus.Instance.enabled);});
foreach(string fault in new[]{"set","send","live-color","cached-color"})Test("cosmetic failure cannot stop win notification "+fault,()=>{Population(3,3);var p=PlayerCatch.AllPlayerControls[0];if(fault=="set")p.ThrowColor=true;if(fault=="send")CustomRpcSender.ThrowSend=true;if(fault=="live-color")p.Data.DefaultOutfit.BadColor=true;if(fault=="cached-color")Camouflage.PlayerSkins[0].BadColor=true;GameEndChecker.Prefix();Check(Probe.EndCalls==1&&CustomWinnerHolder.WinnerIds.Count==3);});
foreach(var winner in new[]{CustomWinner.Crewmate,CustomWinner.Special,CustomWinner.Draw,CustomWinner.None})Test("special or task win survives cosmetic fault "+winner,()=>{Population(1,2);PlayerCatch.AllPlayerControls[0].ThrowColor=true;GameEndChecker.SetPredicate(new FixedPredicate{Winner=winner,Reason=winner==CustomWinner.Crewmate?GameOverReason.CrewmatesByTask:GameOverReason.ImpostorsByKill});GameEndChecker.Prefix();Check(Probe.EndCalls==1&&CustomWinnerHolder.WinnerTeam==winner);});
Test("sabotage winner stays locked",()=>{Population(1,2);P(3).ThrowColor=true;GameEndChecker.SetPredicate(new FixedPredicate{Winner=CustomWinner.Impostor,Reason=GameOverReason.ImpostorsBySabotage});GameEndChecker.Prefix();Check(Probe.EndCalls==1&&Probe.EndReason==GameOverReason.ImpostorsBySabotage&&CustomWinnerHolder.WinnerTeam==CustomWinner.Impostor);});
Test("repeated end check does not start multiple coroutines",()=>{Population(3,3);for(int i=0;i<100;i++)GameEndChecker.Prefix();Check(Probe.Coroutines==1&&Probe.EndCalls==1);});
Test("restoration failure is isolated to one player",()=>{Population(3,3);PlayerCatch.AllPlayerControls[0].ThrowColor=true;GameEndChecker.Prefix();Check(Probe.EndCalls==1&&PlayerCatch.AllPlayerControls.Skip(1).All(p=>p.Data.DefaultOutfit.RawColor==2));});
Test("five consecutive round caches do not retain failed targets",()=>{for(int round=0;round<5;round++){Reset();Population(3,3);var p=PlayerCatch.AllPlayerControls[0];p.Data.DefaultOutfit.BadPet=round==4;GameEndChecker.Prefix();Check(Probe.EndCalls==1&&CustomWinnerHolder.WinnerIds.Count==3);}});
Test("dead state and winner lists preserved through actual coroutine",()=>{Population(3,3);P(6).Data.IsDead=true;PlayerCatch.AllPlayerControls[0].ThrowColor=true;GameEndChecker.Prefix();Check(Probe.EndCalls==1&&PlayerCatch.AllPlayerControls[6].Data.IsDead&&PlayerCatch.AllPlayerControls.Take(6).All(p=>!p.Data.IsDead)&&CustomWinnerHolder.WinnerIds.SetEquals(new byte[]{0,1,2}));});
Console.WriteLine($"CAMOUFLAGE_ENDGAME_RESULT {passed} passed, {failed} failed");Environment.ExitCode=failed==0?0:1;
}
}
